async function scanBundle(input, deliver) {
  const decoder = new TextDecoder("utf-8");
  let pending = "";
  let lineNumber = 1;
  let delivered = 0;

  function parseLine(text, line) {
    const source = text.endsWith("\r") ? text.slice(0, -1) : text;

    if (source.trim() === "") {
      return { blank: true };
    }

    try {
      return { blank: false, value: JSON.parse(source) };
    } catch {
      const error = new Error("Invalid JSON line");
      error.code = "BAD_LINE";
      error.line = line;
      throw error;
    }
  }

  async function processCompleteLines(text) {
    pending += text;

    while (true) {
      const newline = pending.indexOf("\n");
      if (newline === -1) return false;

      const record = parseLine(pending.slice(0, newline), lineNumber);
      pending = pending.slice(newline + 1);

      if (!record.blank) {
        delivered += 1;
        if ((await deliver(record.value, lineNumber)) === false) {
          return true;
        }
      }

      lineNumber += 1;
    }
  }

  try {
    while (true) {
      const chunk = await input.read();

      if (chunk === null) {
        if (await processCompleteLines(decoder.decode())) {
          return delivered;
        }

        if (pending !== "") {
          const record = parseLine(pending, lineNumber);
          if (!record.blank) {
            delivered += 1;
            await deliver(record.value, lineNumber);
          }
        }

        return delivered;
      }

      if (await processCompleteLines(decoder.decode(chunk, { stream: true }))) {
        return delivered;
      }
    }
  } finally {
    await input.close();
  }
}
